package cl.ipvg.georegistro;
import android.os.Bundle; import android.widget.Toast; import androidx.appcompat.app.AppCompatActivity; import androidx.recyclerview.widget.*; import com.google.firebase.firestore.*; import java.util.*;
public class HistorialActivity extends AppCompatActivity{List<Incidencia> l=new ArrayList<>(); IncidenciaAdapter a; protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_historial);RecyclerView r=findViewById(R.id.recyclerIncidencias);r.setLayoutManager(new LinearLayoutManager(this));a=new IncidenciaAdapter(l);r.setAdapter(a);FirebaseFirestore.getInstance().collection("incidencias").orderBy("fechaCreacion",Query.Direction.DESCENDING).get().addOnSuccessListener(q->{l.clear();l.addAll(q.toObjects(Incidencia.class));a.notifyDataSetChanged();}).addOnFailureListener(e->Toast.makeText(this,"No se pudo cargar el historial.",Toast.LENGTH_LONG).show());}}